'use strict';

// Binds the network controls of the local load-error screen. The screen is a
// data: page generated by the main process (src/main/error-screen.js): remote
// pages cannot produce a top-level data: navigation, and every page that enters
// the main window otherwise has a SoundCloud URL, so this binding only ever
// runs on the page the main process loaded.
//
// Nothing from the normal cusade boot runs on this page: entering boot bails
// out here, so no site styling, translation observers or automation touch it.
// A successful apply or reset makes the main process navigate back to
// SoundCloud, which also serves as the immediate real-world connection check.

const { wireNetworkControls } = require('./network-controls.js');

function isNetworkScreenPage() {
  if (window.location.protocol !== 'data:') return false;
  return document.documentElement?.getAttribute('data-cusade-network-screen') === 'load-failure';
}

function bindNetworkScreen() {
  const language = (document.documentElement.lang || '').toLowerCase() === 'ru' ? 'ru' : 'en';
  wireNetworkControls(document, { language })
    .catch(error => console.error('Could not load network settings:', error));
}

module.exports = { isNetworkScreenPage, bindNetworkScreen };
